import{questReadSource,questWriteSource,questLogGuardSource}from'./quest-runtime.js';
import {sceneActions} from './authoring-model.js';
import {sceneSource} from './scene-compiler.js';
import{hmActionSource}from'./field-rom.js';
import{HMS}from'./field-model.js';
import{inBounds,uid}from'./model.js';
import{wrapDialogue}from'./world-model.js';
export const EVENT_ACTIONS={say:'Show dialogue',wait:'Wait',move:'Move player / NPC',warp:'Go to another map',gate:'Open a gate',hm:'HM / field action',choice:'Ask Yes / No',condition:'Only continue if…',item:'Give / take an item',money:'Give / take money',heal:'Heal the party',shop:'Open a shop',battle:'Trainer battle',giveMon:'Give a Pokémon',quest:'Set quest progress',sound:'Play a sound',music:'Change background music',fade:'Fade screen',portrait:'Show Pokémon portrait'};
export const ADVANCED_EVENT_TYPES=new Set(['choice','condition','item','money','heal','shop','battle','giveMon','quest','sound','music','fade','portrait']);
export function needsQuest(n){return(n.runtime?.action==='scene'&&(n.runtime.repeat==='once'||!!n.runtime.areaActiveFlag||!!n.runtime.counterId||[...n.runtime.conditions||[],...sceneActions(n).flatMap(s=>s.conditions||[])].some(c=>['flag','event','visited','variable','option'].includes(c.kind))||sceneActions(n).some(s=>['flag','set','add','completeField'].includes(s.type))))||!!n.runtime?.onceFlag||sequenceOf(n).some(s=>s.type==='quest'||s.type==='condition'&&s.kind==='quest');}
export function sequenceOf(n){return n.runtime?.action==='scene'?sceneActions(n):n.runtime?.action==='dialogue'?[{type:'say',text:n.runtime.text}]:n.runtime?.steps||[];}
export function validateEvent(n,project,map=null){
 if(n.runtime?.action==='scene'){if(!Array.isArray(n.runtime.steps)||JSON.stringify(n.runtime).length>256000)throw Error('The scene draft is too large or invalid.');sceneActions(n);return;}
 const r=n.runtime;if(!r)return;if(r.action==='dialogue'){wrapDialogue(r.text);return;}
 if(r.action!=='sequence'||!['interact','step'].includes(r.trigger)||!Array.isArray(r.steps)||!r.steps.length||r.steps.length>64)throw Error('An event needs a trigger and 1–64 actions.');
 if(r.steps.some((s,i)=>s.type==='warp'&&i!==r.steps.length-1))throw Error('Put the map change last in the event.');
 if(r.onceFlag&&!project.questFlags?.some(q=>q.id===r.onceFlag))throw Error('Choose an existing named quest flag for this one-time event.');
 for(const s of r.steps){if(!s||!EVENT_ACTIONS[s.type])throw Error('An event action is invalid.');if(s.type==='say')wrapDialogue(s.text);if(s.type==='wait'&&(!Number.isInteger(s.frames)||s.frames<1||s.frames>36000))throw Error('Use a wait from 1 frame to 10 minutes.');if(s.type==='move'&&(!['up','down','left','right'].includes(s.direction)||!Number.isInteger(s.distance)||s.distance<1||s.distance>32||!['player','npc'].includes(s.actor)))throw Error('Choose a movement direction and 1–32 tiles.');if(s.type==='move'&&s.actor==='npc'&&!n.rom?.localId&&!n.npc)throw Error('NPC movement needs an imported NPC event.');if(s.type==='warp'){const m=project.maps.find(m=>m.id===s.to?.mapId);if(!m||!inBounds(m,s.to.x,s.to.y))throw Error('Choose an event destination inside a map.');}if(s.type==='hm'){if(!['flash','strength','rocksmash','cut'].includes(s.effect))throw Error('Choose an HM action.');if(['cut','rocksmash'].includes(s.effect)){const source=map||project.maps.find(m=>m.markers.some(v=>v.id===n.id));if(!(source?.fieldObjects||[]).some(o=>o.id===s.targetId&&o.kind===s.effect))throw Error('Choose the matching rock or tree on this map.');}}if(s.type==='gate'&&typeof s.gateId!=='string')throw Error('Choose a gate to open.');
  const integer=(v,min,max)=>Number.isInteger(v)&&v>=min&&v<=max;if(s.type==='choice')wrapDialogue(s.text);if(s.type==='condition'){if(!['item','money','quest','badge'].includes(s.kind))throw Error('Choose a condition.');if(s.kind==='quest'&&!project.questFlags?.some(q=>q.id===s.questId))throw Error('Choose a named quest flag.');if(s.kind==='item'&&(!integer(s.itemId,1,4095)||!integer(s.quantity,1,999)))throw Error('Choose an item and quantity.');if(s.kind==='money'&&!integer(s.amount,0,999999))throw Error('Use a valid money requirement.');if(s.kind==='badge'&&!integer(s.badge,1,8))throw Error('Choose badge 1–8.');}if(s.type==='item'&&(!integer(s.itemId,1,4095)||!integer(s.quantity,1,999)||!['give','take'].includes(s.operation)))throw Error('Choose give/take, an item and quantity.');if(s.type==='money'&&(!integer(s.amount,0,999999)||!['give','take'].includes(s.operation)))throw Error('Choose give/take and a valid amount.');if(s.type==='shop'&&(!Array.isArray(s.items)||s.items.length<1||s.items.length>50||s.items.some(i=>!integer(i,1,4095))))throw Error('A shop needs 1–50 named items.');if(s.type==='battle'&&!integer(s.trainerId,1,4095))throw Error('Choose a native trainer.');if(s.type==='giveMon'&&(!integer(s.species,1,8191)||!integer(s.level,1,100)||!integer(s.itemId||0,0,4095)))throw Error('Choose a Pokémon, level and held item.');if(s.type==='quest'&&(!project.questFlags?.some(q=>q.id===s.questId)||typeof s.value!=='boolean'))throw Error('Choose a named quest flag and set/clear.');if(s.type==='sound'&&!integer(s.soundId,0,1023)||s.type==='music'&&!integer(s.songId,0,65535)||s.type==='fade'&&!integer(s.mode,0,3)||s.type==='portrait'&&!integer(s.species,1,8191))throw Error('Choose a valid effect.');}
}
export function newEvent(x,y){return{id:uid(),x,y,kind:'event',title:'New interaction',text:'',runtime:{action:'sequence',trigger:'interact',enabled:true,blocksMovement:false,steps:[{type:'say',text:'Hello there!'}]}};}
export function eventSource(n,context={}){
 if(n.runtime?.action==='scene')return sceneSource(n,context);
 const {resolveMap,gateCommands=new Map(),fieldProfile=null,fieldObjects=new Map(),gameProfile=null,questRuntime=null,questFlags=[],npcLocalId=null,nativeGift=null}=context;
 const r=n.runtime,steps=sequenceOf(n),commands=[...(questRuntime?questLogGuardSource('@field_event_end'):[]),'lockall'],data=[];const slot=id=>{const q=questFlags.find(q=>q.id===id);if(!q)throw Error('A quest flag is missing.');return q.slot;};const text=(label,value)=>data.push(label+':\n= '+wrapDialogue(value)+'$');const failed=(label,value)=>{commands.push(label+':','msgbox '+label+'text 4','goto @field_event_end');text(label+'text',value);};if(r.onceFlag){commands.push(...questReadSource(questRuntime,slot(r.onceFlag),'@quest_conflict'),'compare_var_to_value 0x800D 1','goto_if 1 @event_already_done');}
 if((n.rom?.type==='npc'||n.npc)&&(r.trigger||'interact')==='interact')commands.push('faceplayer');
 steps.forEach((s,i)=>{const itemRefs=s.type==='shop'?s.items:s.type==='item'||s.type==='condition'&&s.kind==='item'?[s.itemId]:s.type==='giveMon'&&s.itemId?[s.itemId]:[];if(gameProfile?.itemIds&&itemRefs?.some(id=>!gameProfile.itemIds.includes(id)))throw Error('This event refers to an uninitialised native item.');if(['item','shop','battle','giveMon','portrait'].includes(s.type)&&!gameProfile&&!(s.type==='giveMon'&&nativeGift&&n.creatureGift))throw Error('This action needs native game-table metadata from the opened ROM.');if(s.type==='say'){commands.push('msgbox @text'+i+' 4','closemessage');data.push('@text'+i+':\n= '+wrapDialogue(s.text)+'$');}
 else if(s.type==='wait')commands.push('pause '+s.frames);
 else if(s.type==='move'){const actor=s.actor==='npc'?(npcLocalId??n.rom?.localId):255;if(!Number.isInteger(actor)||actor<1||actor>255)throw Error('This movement needs a valid imported NPC.');commands.push('applymovement '+actor+' @move'+i,'waitmovement '+actor);data.push('@move'+i+':\n'+Array(s.distance).fill('walk_'+s.direction).join('\n')+'\nstep_end');}
 else if(s.type==='warp'){const target=resolveMap?.(s.to.mapId);if(!target)throw Error('The event destination must be included in this ROM export.');if(target.bank>127||target.index>127||s.to.x>127||s.to.y>127)throw Error('This game’s scripted warp needs map/coordinate values below 128. Use a linked portal for larger coordinates.');if(r.onceFlag)commands.push(...questWriteSource(questRuntime,slot(r.onceFlag),true,'@quest_conflict'));commands.push('warp '+target.bank+' '+target.index+' 255 '+s.to.x+' '+s.to.y,'waitstate');}
 else if(s.type==='hm'){const hm=hmActionSource(s,i,{fieldProfile,fieldObjects});commands.push(...hm.commands);data.push(...hm.data);}
 else if(s.type==='choice'){commands.push('msgbox @choice'+i+' 5','compare_var_to_value 0x800D 0','goto_if 1 @field_event_end','closemessage');text('@choice'+i,s.text);}
 else if(s.type==='condition'){const label='@condition'+i,after=label+'pass';if(s.kind==='quest')commands.push(...questReadSource(questRuntime,slot(s.questId),'@quest_conflict'),'compare_var_to_value 0x800D '+(s.value===false?0:1));else if(s.kind==='item'){if(s.itemId>=(gameProfile.itemCount||0))throw Error('A condition item is outside this ROM.');commands.push('checkitem '+s.itemId+' '+s.quantity,'compare_var_to_value 0x800D 1');}else if(s.kind==='money')commands.push('checkmoney '+s.amount+' 0','compare_var_to_value 0x800D 1');else{if(gameProfile?.engine&&gameProfile.engine!=='frlg')throw Error('Badge conditions need this engine’s badge flag adapter.');commands.push('checkflag '+(0x820+s.badge-1));}commands.push('goto_if 1 '+after);failed(label,s.failText||'You have not met this requirement.');commands.push(after+':');}
 else if(s.type==='item'){if(s.itemId>=(gameProfile.itemCount||0))throw Error('An event item is outside this ROM.');const pass='@item'+i+'pass';commands.push((s.operation==='give'?'checkitemspace ':'checkitem ')+s.itemId+' '+s.quantity,'compare_var_to_value 0x800D 1','goto_if 1 '+pass,'msgbox @item'+i+'fail 4','goto @field_event_end',pass+':',(s.operation==='give'?'additem ':'removeitem ')+s.itemId+' '+s.quantity,'compare_var_to_value 0x800D 1','goto_if 0 @item'+i+'error','goto @item'+i+'after','@item'+i+'error:','msgbox @item'+i+'fail 4','goto @field_event_end','@item'+i+'after:');text('@item'+i+'fail',s.operation==='give'?'There is no room in your Bag.':'You do not have the required item.');}
 else if(s.type==='money'){if(s.operation==='take'){commands.push('checkmoney '+s.amount+' 0','compare_var_to_value 0x800D 1','goto_if 1 @money'+i+'pass');failed('@money'+i+'fail','You do not have enough money.');commands.push('@money'+i+'pass:');}commands.push((s.operation==='give'?'addmoney ':'removemoney ')+s.amount+' 0');}
 else if(s.type==='heal')commands.push('special 0');
 else if(s.type==='shop'){if(s.items.some(id=>id>=(gameProfile.itemCount||0)))throw Error('A shop item is outside this ROM.');commands.push('closemessage','pokemart @shop'+i);data.push('.align 2','@shop'+i+':','.hword '+[...s.items,0].join(' '));}
 else if(s.type==='battle'){if(s.trainerId>=(gameProfile.trainerCount||0))throw Error('Choose an existing trainer slot.');commands.push('closemessage','trainerbattle 1 '+s.trainerId+' '+(npcLocalId??n.rom?.localId??0)+' @battle'+i+'intro @battle'+i+'defeat @battle'+i+'after','@battle'+i+'after:');text('@battle'+i+'intro',s.intro||'Let us battle!');text('@battle'+i+'defeat',s.defeat||'You won!');}
 else if(s.type==='giveMon'){if(nativeGift&&n.creatureGift){if(s.itemId)throw Error('Native custom-form gifts do not yet support held items.');commands.push(nativeGift(s));}else{if(!gameProfile||s.species>=(gameProfile.speciesCount||0)||(s.itemId||0)>=(gameProfile.itemCount||0))throw Error('Choose a Pokémon and item from this ROM.');commands.push('givemon '+s.species+' '+s.level+' '+(s.itemId||0)+' 0 0 0');}commands.push('compare_var_to_value 0x800D 2','goto_if 0 @gift'+i+'ok');failed('@gift'+i+'full','Your party and storage have no room.');commands.push('@gift'+i+'ok:');}
 else if(s.type==='quest')commands.push(...questWriteSource(questRuntime,slot(s.questId),s.value,'@quest_conflict'));
 else if(s.type==='sound')commands.push('playse '+s.soundId,'waitse');
 else if(s.type==='music')commands.push('playbgm '+s.songId+' 0');
 else if(s.type==='fade')commands.push('fadescreen '+s.mode);
 else if(s.type==='portrait')commands.push('showmonpic '+s.species+' 10 3','waitbuttonpress','hidemonpic');
 else if(s.type==='gate'){const block=gateCommands.get(s.gateId);if(!block)throw Error('The event refers to a missing or unsupported gate.');commands.push(...block);}});
 if(r.onceFlag&&!steps.some(s=>s.type==='warp'))commands.push(...questWriteSource(questRuntime,slot(r.onceFlag),true,'@quest_conflict'));commands.push('goto @field_event_end');if(r.onceFlag)failed('@event_already_done',r.repeatText||'You have already completed this.');if(needsQuest(n))failed('@quest_conflict','This save belongs to another project. Use its project or a fresh test save.');commands.push('@field_event_end:','closemessage','releaseall','end');return commands.join('\n')+'\n'+data.join('\n');
}
export function eventsAt(map,x,y,trigger){return map.markers.filter(n=>n.runtime&&n.runtime.enabled!==false&&(n.runtime.trigger||'interact')===trigger&&n.x===x&&n.y===y);}
